 private int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 private LinearLayout column(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(VERTICAL);return v;}
 private LinearLayout row(){LinearLayout v=new LinearLayout(getContext());v.setOrientation(HORIZONTAL);return v;}
 private HorizontalScrollView horizontal(LinearLayout v){HorizontalScrollView s=new HorizontalScrollView(getContext());s.setHorizontalScrollBarEnabled(false);s.addView(v);return s;}
 private void label(LinearLayout parent,String text){TextView t=new TextView(getContext());t.setText(text);parent.addView(t);}
 private Button button(LinearLayout parent,String text,Action fn){Button b=new Button(getContext());b.setText(text);b.setMinHeight(dp(48));parent.addView(b,new LayoutParams(-2,dp(48)));b.setOnClickListener(v->guard(fn));return b;}
 private EditText edit(LinearLayout parent,String label,String tag){label(parent,label);EditText e=new EditText(getContext());e.setTag(tag);e.setMinHeight(dp(48));e.setSingleLine(true);parent.addView(e);e.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int count,int after){}public void onTextChanged(CharSequence s,int a,int before,int count){if(!filling){prepared=new JSONObject();schedule();}}public void afterTextChanged(android.text.Editable e){}});return e;}
 private void adapter(Spinner spinner,List<String>values){ArrayAdapter<String>a=new ArrayAdapter<String>(getContext(),android.R.layout.simple_spinner_item,values){public View getView(int p,View reuse,android.view.ViewGroup parent){TextView t=(TextView)super.getView(p,reuse,parent);t.setTextColor(dark?Color.WHITE:Color.rgb(23,34,53));return t;}public View getDropDownView(int p,View reuse,android.view.ViewGroup parent){TextView t=(TextView)super.getDropDownView(p,reuse,parent);t.setTextColor(dark?Color.WHITE:Color.rgb(23,34,53));t.setBackgroundColor(dark?Color.rgb(32,46,66):Color.WHITE);t.setMinHeight(dp(48));return t;}};a.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);spinner.setAdapter(a);}
 private void list(ListView view,List<String>values){view.setAdapter(new ArrayAdapter<String>(getContext(),android.R.layout.simple_list_item_1,values){public View getView(int p,View reuse,android.view.ViewGroup parent){TextView t=(TextView)super.getView(p,reuse,parent);t.setTextColor(dark?Color.WHITE:Color.rgb(23,34,53));t.setMinHeight(dp(48));return t;}});}
 private void guard(Action fn){try{fn.run();}catch(Exception e){if(status!=null)status.setText(e.getMessage()==null?e.toString():e.getMessage());}}
 private void schedule(){removeCallbacks(saveDraft);postDelayed(saveDraft,300);}
 private void loadSavedInstruments()throws Exception{savedIds.clear();List<String>names=new ArrayList<>();JSONObject r=store.get(selectedId),m=r.getString("kind").equals("mirror")?r.getJSONObject("draft").getJSONObject("mirror"):r.getJSONObject("mirror");JSONArray holdings=m.getJSONArray("holdings");for(int i=0;i<holdings.length();i++){JSONObject h=holdings.getJSONObject(i);savedIds.add(h.getString("instrumentId"));names.add(h.getString("name")+" / "+h.getString("instrumentId"));}adapter(savedInstruments,names);}
 private void show(int m){mode=m;if(m==1&&status!=null)status.setText("独立历史 "+historyIds.size()+" 个版本 · 选择版本查看差异；未改账本");form.setVisibility(m==0?VISIBLE:GONE);historyPage.setVisibility(m==1?VISIBLE:GONE);readPage.setVisibility(m==2?VISIBLE:GONE);}
 private static String value(Object v){return v instanceof Number?v.toString():"未知";}
 private void refresh()throws Exception{PortfolioMirrorModel.need(readInputs!=null,"没有只读提供器");input=readInputs.read();PortfolioMirrorModel.index(input);boolean was=filling;filling=true;accountIds.clear();List<String>names=new ArrayList<>();JSONArray a=input.getJSONArray("accounts");for(int i=0;i<a.length();i++){JSONObject r=a.getJSONObject(i);if(r.optString("type").equals("ledger")){accountIds.add(r.getString("id"));names.add(r.optString("name")+" / "+r.getString("id"));}}adapter(accounts,names);int selected=accountIds.indexOf(accountId);if(selected>=0)accounts.setSelection(selected);else if(!accountIds.isEmpty())accountId=accountIds.get(0);historyIds.clear();names=new ArrayList<>();JSONArray catalog=store.catalog();for(int i=0;i<catalog.length();i++){JSONObject r=catalog.getJSONObject(i);historyIds.add(r.getString("id"));names.add(r.getString("savedAt")+" / "+r.getString("kind")+" / "+r.getString("accountId"));}list(history,names);filling=was;}
 public void previewImport(String text)throws Exception{pending=PortfolioMirrorModel.decode(text);pendingCatalog=store.catalogFingerprint();prepared=new JSONObject();filling=true;List<String>names=new ArrayList<>();if(pending.getString("kind").equals("source")){JSONArray ss=pending.getJSONArray("snapshots");for(int i=0;i<ss.length();i++){JSONObject s=ss.getJSONObject(i);names.add(i+" / "+s.getString("snapshotAsOf")+" / "+s.getString("sourceLabel"));}}adapter(snapshots,names);filling=false;accountAck.setChecked(false);if(pending.getString("kind").equals("source")){chooseSnapshot(0);show(0);status.setText("仅预览；逐行绑定完整身份并核对账户，预览差异后明确保存");}else{showOriginal(pending.getString("rawUtf8"));status.setText("本机镜像备份仅预览，未覆盖已有版本");}persist();}
 private void chooseSnapshot(int selected)throws Exception{PortfolioMirrorModel.need(pending.optString("kind").equals("source")&&selected>=0&&selected<pending.getJSONArray("snapshots").length(),"没有源快照");boolean restoring=filling;filling=true;selectedSnapshot=selected;prepared=new JSONObject();bindings=new JSONArray();JSONObject s=pending.getJSONArray("snapshots").getJSONObject(selected);snapshots.setSelection(selected);snapshotAsOf.setText(s.getString("snapshotAsOf"));sourceLabel.setText(s.getString("sourceLabel"));if(!restoring){accountAck.setChecked(false);accountReason.setText("");completeAck.setChecked(false);completenessReason.setText("");}JSONArray hs=s.getJSONArray("holdings");List<String>names=new ArrayList<>();for(int i=0;i<hs.length();i++){JSONObject r=hs.getJSONObject(i);bindings.put(PortfolioMirrorModel.object("instrumentId",r.getString("instrumentId"),"reason",""));names.add(r.getString("code")+" "+r.getString("name")+" · 数量"+value(r.get("quantity"))+" · 成本"+value(r.get("costValue"))+" · "+(r.getString("instrumentId").isEmpty()?"待明确身份":r.getString("instrumentId")));}list(rows,names);selectedRow=-1;adapter(instruments,new ArrayList<>());filling=restoring;if(bindings.length()>0)chooseRow(0);if(!restoring)persist();}
 private void chooseRow(int position)throws Exception{PortfolioMirrorModel.need(position>=0&&position<bindings.length(),"先选择源持仓行");selectedRow=position;JSONObject r=pending.getJSONArray("snapshots").getJSONObject(selectedSnapshot).getJSONArray("holdings").getJSONObject(position),b=bindings.getJSONObject(position);instrumentIds.clear();List<String>names=new ArrayList<>();instrumentIds.add("");names.add("请选择明确完整证券身份");JSONArray roster=input.getJSONArray("instruments");for(int i=0;i<roster.length();i++){JSONObject ins=roster.getJSONObject(i);String id=ins.getString("id");if(PortfolioMirrorModel.fullId(id,true)&&id.split(":")[2].equals(r.getString("code"))){instrumentIds.add(id);names.add(ins.optString("name")+" / "+id);}}adapter(instruments,names);int chosen=instrumentIds.indexOf(b.optString("instrumentId"));if(chosen>=0)instruments.setSelection(chosen);boolean was=filling;filling=true;identityReason.setText(b.optString("reason"));filling=was;rowInfo.setText("源代码 "+r.getString("code")+" / 市场提示 "+r.getString("marketHint")+" / 类型提示 "+r.getString("typeHint")+" / 原价 "+value(r.get("currentPrice"))+"；数字0保留，未知不填0。");}
 private String chosenInstrument(){int i=instruments.getSelectedItemPosition();return i>=0&&i<instrumentIds.size()?instrumentIds.get(i):"";}
 private void checkEditorCommitted()throws Exception{if(selectedRow>=0&&selectedRow<bindings.length()){JSONObject b=bindings.getJSONObject(selectedRow);PortfolioMirrorModel.need(chosenInstrument().equals(b.optString("instrumentId"))&&identityReason.getText().toString().equals(b.optString("reason")),"此行身份或依据尚未确认；先点击确认此行完整身份");}}
 private void bindRow()throws Exception{PortfolioMirrorModel.need(selectedRow>=0&&selectedRow<bindings.length()&&!chosenInstrument().isEmpty(),"需选择明确完整证券身份");bindings.put(selectedRow,PortfolioMirrorModel.object("instrumentId",chosenInstrument(),"reason",identityReason.getText().toString()));prepared=new JSONObject();persist();status.setText("此行已明确绑定 "+chosenInstrument());}
 private JSONObject options()throws Exception{return PortfolioMirrorModel.object("snapshotAsOf",snapshotAsOf.getText().toString().trim(),"sourceLabel",sourceLabel.getText().toString().trim(),"accountBindingReason",accountReason.getText().toString(),"accountAcknowledged",accountAck.isChecked(),"completeAcknowledged",completeAck.isChecked(),"completenessReason",completenessReason.getText().toString());}
 private void previewDifference()throws Exception{checkEditorCommitted();PortfolioMirrorModel.need(pending.optString("kind").equals("source"),"先导入持仓源文件");prepared=PortfolioMirrorModel.prepare(pending,selectedSnapshot,readInputs.read(),accountId,bindings,options());pendingCatalog=store.catalogFingerprint();displayDifference(prepared.getJSONObject("reconciliation"));persist();}
 private void displayDifference(JSONObject r)throws Exception{StringBuilder text=new StringBuilder("只读对账 · "+r.getString("scope")+"\n源时点 "+r.getString("mirrorAsOf")+" / 账本时点 "+r.getString("ledgerAsOf")+"\n现金 源:"+value(r.get("mirrorCash"))+" / 账本:"+value(r.get("ledgerCash"))+" / 可比差值:"+value(r.get("cashDelta"))+"\n");JSONArray ps=r.getJSONArray("rows");for(int i=0;i<ps.length();i++){JSONObject p=ps.getJSONObject(i);text.append(p.getString("instrumentId")).append(" · 数量 源").append(value(p.get("mirrorQuantity"))).append(" /账本").append(value(p.get("ledgerQuantity"))).append(" /差").append(value(p.get("quantityDelta"))).append(" · 成本 源").append(value(p.get("mirrorCost"))).append(" /账本").append(value(p.get("ledgerCost"))).append(" /差").append(value(p.get("costDelta"))).append(" · ").append(p.getString("status")).append('\n');}text.append("\n缺数、不同现金时点与动态收益归因不自动推断。以下完整冻结证据：\n").append(r.toString(2));showOriginal(text.toString());}
 public void confirmImport()throws Exception{PortfolioMirrorModel.need(pending.length()>0,"没有待确认预览");if(pending.getString("kind").equals("backup")){JSONArray records=pending.getJSONObject("original").getJSONArray("records"),ordered=new JSONArray();for(String kind:new String[]{"mirror","comparison"})for(int i=0;i<records.length();i++)if(records.getJSONObject(i).getString("kind").equals(kind))ordered.put(records.get(i));PortfolioMirrorModel.need(ordered.length()==records.length(),"备份有未知记录类别");store.append(ordered,pendingCatalog);}else{checkEditorCommitted();PortfolioMirrorModel.need(prepared.length()>0,"先明确绑定并预览差异");JSONArray ids=new JSONArray();for(int i=0;i<bindings.length();i++)ids.put(bindings.getJSONObject(i).getString("instrumentId"));JSONObject fresh=PortfolioMirrorModel.scope(readInputs.read(),accountId,ids),frozen=new JSONObject(prepared.getJSONObject("scope").toString());fresh.remove("capturedAt");fresh.remove("sourceLabel");frozen.remove("capturedAt");frozen.remove("sourceLabel");PortfolioMirrorModel.need(PortfolioMirrorModel.equal(fresh,frozen),"账户/证券/账本已变化，请重新预览差异");JSONObject record=PortfolioMirrorModel.version(prepared,Instant.now().toString());store.append(new JSONArray().put(record),pendingCatalog);selectedId=record.getString("id");loadSavedInstruments();}pending=new JSONObject();prepared=new JSONObject();bindings=new JSONArray();pendingCatalog="";refresh();show(1);persist();status.setText("独立镜像版本已保存；未改账本、现金或行情");}
 public void cancelImport(){pending=new JSONObject();prepared=new JSONObject();bindings=new JSONArray();pendingCatalog="";rows.setAdapter(null);readText="";readOffset=0;reader.setText("");show(0);guard(this::persist);status.setText("预览已取消");}
 private void showOriginal(String text){readText=text;readOffset=0;renderReader();show(2);}
 private void renderReader(){int n=readText.codePointCount(0,readText.length()),start=readText.offsetByCodePoints(0,Math.min(readOffset,n)),end=readText.offsetByCodePoints(0,Math.min(readOffset+24000,n));reader.setText(readText.substring(start,end));status.setText("完整文本分段 "+readOffset+"–"+Math.min(readOffset+24000,n)+" / "+n+"；全量导出不截断");}
 private void locate()throws Exception{PortfolioMirrorModel.need(!selectedId.isEmpty()&&opener!=null,"先选保存版本");JSONObject r=store.get(selectedId),m=r.getString("kind").equals("mirror")?r.getJSONObject("draft").getJSONObject("mirror"):r.getJSONObject("mirror");JSONArray hs=m.getJSONArray("holdings");PortfolioMirrorModel.need(hs.length()>0,"空镜像没有证券");if(savedIds.isEmpty())loadSavedInstruments();int selected=savedInstruments.getSelectedItemPosition();PortfolioMirrorModel.need(selected>=0&&selected<savedIds.size(),"请选择镜像完整身份");String id=savedIds.get(selected);boolean bound=false;for(int i=0;i<hs.length();i++)if(hs.getJSONObject(i).getString("instrumentId").equals(id))bound=true;PortfolioMirrorModel.need(bound,"所选完整身份不属于此镜像版本");JSONObject current=PortfolioMirrorModel.index(readInputs.read()).getJSONObject("instruments").optJSONObject(id);PortfolioMirrorModel.need(current!=null&&PortfolioMirrorModel.fullId(id,true)&&current.getString("id").equals(id),"完整证券身份不可定位，未按代码改绑");persist();opener.open(new JSONObject(current.toString()));}
 public boolean back(){if(mode==2){show(pending.length()>0?0:1);guard(this::persist);return true;}if(mode==1){show(0);return true;}guard(this::persist);return false;}
